  const gbpShort=n=>Math.abs(n)>=1e6?"£"+(n/1e6).toFixed(2)+"M":"£"+Math.round(n/1e3)+"k";
  const number=n=>Math.round(n).toLocaleString("en-GB");
  const hectares=n=>Math.round(n).toLocaleString("id-ID")+" ha";
  const kilo=v=>Math.abs(v)>=1e6?(v/1e6).toFixed(1)+"M":(v/1e3).toFixed(0)+"k";
  const pct=(n,d=1,sign=false)=>(sign&&n>0?"+":"")+n.toFixed(d).replace(".",",")+"%";
  const short=(s,n=28)=>s.length>n?s.slice(0,n-1)+"…":s;
  const MONTHS=["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu","Sep","Okt","Nov","Des"];
  const monthName=l=>{const [y,m]=l.split("-");return MONTHS[+m-1]+" "+y;};
